-- Tracked exercises (e1-e4) and their body regions, from e4_app_bundle/exercise_catalog.json
-- (generated by tool/tracked_exercises/make_migrations.py). Idempotent: running it twice changes nothing.
-- Undo: 2026_10_27_01_tracked_exercises.down.sql. The PHP endpoints do the same on first use
-- (reed/tracked_exercises_lib.php: ensure_tracking_schema).
CREATE TABLE IF NOT EXISTS `body_region` (
  `id` VARCHAR(16) NOT NULL PRIMARY KEY,
  `label` VARCHAR(64) NOT NULL,
  `display_order` INT NOT NULL
) DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `tracked_exercise` (
  `id` VARCHAR(8) NOT NULL PRIMARY KEY,
  `body_region` VARCHAR(16) NOT NULL,
  `display_order` INT NOT NULL,
  `name` VARCHAR(255) NOT NULL,
  `side_kind` VARCHAR(8) NOT NULL,
  `side_question` VARCHAR(255) NOT NULL,
  `side_meaning` VARCHAR(255) NOT NULL,
  `camera` TEXT NULL,
  `instructions` TEXT NOT NULL,
  `classes` TEXT NOT NULL,
  `model_bundle` VARCHAR(64) NOT NULL,
  `model_config` VARCHAR(64) NOT NULL,
  `model_file` VARCHAR(64) NOT NULL,
  KEY `idx_tracked_region` (`body_region`, `display_order`),
  CONSTRAINT `fk_tracked_region` FOREIGN KEY (`body_region`) REFERENCES `body_region` (`id`),
  CONSTRAINT `chk_tracked_side_kind` CHECK (`side_kind` IN ('arm', 'leg'))
) DEFAULT CHARSET=utf8mb4;

INSERT INTO `body_region` (`id`, `label`, `display_order`) VALUES ('shoulder', 'Shoulder', 1)
  ON DUPLICATE KEY UPDATE `label` = VALUES(`label`), `display_order` = VALUES(`display_order`);
INSERT INTO `body_region` (`id`, `label`, `display_order`) VALUES ('hip', 'Hip', 2)
  ON DUPLICATE KEY UPDATE `label` = VALUES(`label`), `display_order` = VALUES(`display_order`);

INSERT INTO `tracked_exercise` (`id`, `body_region`, `display_order`, `name`, `side_kind`, `side_question`, `side_meaning`, `camera`, `instructions`, `classes`, `model_bundle`, `model_config`, `model_file`)
  VALUES ('e1', 'shoulder', 1, 'Stick elevation (active-assisted forward elevation)', 'arm', 'Which arm is the injured one?', 'the injured arm (both hands hold the stick)', 'from the front, upper body and arms in view (from the knees up)', '["Stand facing the phone, holding a stick with both hands, arms straight down.","Stand still for 2 seconds.","Lift the stick forward and up with straight elbows, then lower it all the way down."]', '["good","elb","rngdown","imb"]', 'shoulder_app_bundle', 'mt_final.json', 'mt_e1.onnx')
  ON DUPLICATE KEY UPDATE `body_region` = VALUES(`body_region`), `display_order` = VALUES(`display_order`), `name` = VALUES(`name`), `side_kind` = VALUES(`side_kind`), `side_question` = VALUES(`side_question`), `side_meaning` = VALUES(`side_meaning`), `camera` = VALUES(`camera`), `instructions` = VALUES(`instructions`), `classes` = VALUES(`classes`), `model_bundle` = VALUES(`model_bundle`), `model_config` = VALUES(`model_config`), `model_file` = VALUES(`model_file`);
INSERT INTO `tracked_exercise` (`id`, `body_region`, `display_order`, `name`, `side_kind`, `side_question`, `side_meaning`, `camera`, `instructions`, `classes`, `model_bundle`, `model_config`, `model_file`)
  VALUES ('e2', 'shoulder', 2, 'Arm abduction', 'arm', 'Which arm will you lift?', 'the working arm', 'from the front, upper body and arms in view (from the knees up)', '["Stand facing the phone, arms by your sides.","Stand still for 2 seconds.","Lift the arm sideways with a straight elbow, without shrugging or leaning, then lower it to your side."]', '["good","elb","rngdown","shld","lean"]', 'shoulder_app_bundle', 'mt_final.json', 'mt_e2.onnx')
  ON DUPLICATE KEY UPDATE `body_region` = VALUES(`body_region`), `display_order` = VALUES(`display_order`), `name` = VALUES(`name`), `side_kind` = VALUES(`side_kind`), `side_question` = VALUES(`side_question`), `side_meaning` = VALUES(`side_meaning`), `camera` = VALUES(`camera`), `instructions` = VALUES(`instructions`), `classes` = VALUES(`classes`), `model_bundle` = VALUES(`model_bundle`), `model_config` = VALUES(`model_config`), `model_file` = VALUES(`model_file`);
INSERT INTO `tracked_exercise` (`id`, `body_region`, `display_order`, `name`, `side_kind`, `side_question`, `side_meaning`, `camera`, `instructions`, `classes`, `model_bundle`, `model_config`, `model_file`)
  VALUES ('e3', 'shoulder', 3, 'Arm rotation (elbow at the side)', 'arm', 'Which arm will you rotate?', 'the working arm', 'from the front, upper body and arms in view (from the knees up)', '["Stand facing the phone, elbow bent at 90 degrees and against your side.","Stand still for 2 seconds.","Rotate the forearm outward and back, keeping the elbow against your body."]', '["good","wrong"]', 'shoulder_app_bundle', 'mt_final.json', 'mt_e3.onnx')
  ON DUPLICATE KEY UPDATE `body_region` = VALUES(`body_region`), `display_order` = VALUES(`display_order`), `name` = VALUES(`name`), `side_kind` = VALUES(`side_kind`), `side_question` = VALUES(`side_question`), `side_meaning` = VALUES(`side_meaning`), `camera` = VALUES(`camera`), `instructions` = VALUES(`instructions`), `classes` = VALUES(`classes`), `model_bundle` = VALUES(`model_bundle`), `model_config` = VALUES(`model_config`), `model_file` = VALUES(`model_file`);
INSERT INTO `tracked_exercise` (`id`, `body_region`, `display_order`, `name`, `side_kind`, `side_question`, `side_meaning`, `camera`, `instructions`, `classes`, `model_bundle`, `model_config`, `model_file`)
  VALUES ('e4', 'hip', 1, 'Standing hip abduction (chair support)', 'leg', 'Which leg will you lift?', 'the lifted leg (stand on the other leg, holding the chair)', 'from the FRONT, the WHOLE body in view including both feet (unlike e1-e3: the ankles are the main points), phone upright at hip height about 2-3 m away; the chair beside the standing leg, the patient holding it; image NOT mirrored (un-mirror the selfie preview before MediaPipe), upright (rotate by the sensor orientation)', '["Stand facing the phone, with a chair beside you; hold it with the hand on the side of the leg you stand on. Your whole body, feet included, must be in view.","Stand still for 2 seconds.","Lift the other leg sideways, knee straight and trunk upright, then lower it with control.","Lift only as far as you can with a good form: your physiotherapist sets your target."]', '["good","knee","leanin","leanout"]', 'e4_app_bundle', 'e4_head.json', 'mt_e4.onnx')
  ON DUPLICATE KEY UPDATE `body_region` = VALUES(`body_region`), `display_order` = VALUES(`display_order`), `name` = VALUES(`name`), `side_kind` = VALUES(`side_kind`), `side_question` = VALUES(`side_question`), `side_meaning` = VALUES(`side_meaning`), `camera` = VALUES(`camera`), `instructions` = VALUES(`instructions`), `classes` = VALUES(`classes`), `model_bundle` = VALUES(`model_bundle`), `model_config` = VALUES(`model_config`), `model_file` = VALUES(`model_file`);
